using FluentValidation;
namespace FintechApp.Requests.UserActionHistory { public class UpdateUserActionHistoryRequest { public int UserHistoryID { get; set; } public int UserID { get; set; } public string Action { get; set; } = string.Empty; public string Description { get; set; } = string.Empty; public string Status { get; set; } = string.Empty; public string IPAddress { get; set; } = string.Empty; } public class UpdateUserActionHistoryRequestValidator : AbstractValidator<UpdateUserActionHistoryRequest> { public UpdateUserActionHistoryRequestValidator() { RuleFor(x => x.UserHistoryID).GreaterThan(0); } } }
